        var prototype=Map(owner,"prototypes")[id].AsGodotDictionary();var actor=prototype["actor"].As<Resource>();var bones=Get(Values(actor),"rig_bones",new GArray()).AsGodotArray();var saved=state["bones"].AsGodotDictionary();var animated=new Settings();state["bones"]=new Settings();try{foreach(var value in bones){string name=value.AsGodotDictionary()["name"].AsString();animated[name]=bone_world(owner,id,name,time);}}finally{state["bones"]=saved;}
        var settings=config["bone_settings"].AsGodotDictionary();float dt=(float)h;foreach(var key in saved.Keys){string name=key.AsString();var bone=saved[key].AsGodotDictionary();var localConfig=config.Duplicate();localConfig.Merge(Get(settings,name,new Settings()).AsGodotDictionary(),true);if(!Get(localConfig,"enabled",true).AsBool())continue;var basis=animated[name].AsTransform3D();var anchor=basis.Origin;int parent=bones[bone["index"].AsInt32()].AsGodotDictionary()["parent"].AsInt32();if(parent>=0){string parentName=bones[parent].AsGodotDictionary()["name"].AsString();if(saved.ContainsKey(parentName)&&Get(Get(settings,parentName,new Settings()).AsGodotDictionary(),"enabled",true).AsBool())anchor=(saved[parentName].AsGodotDictionary()["pose"].AsTransform3D()*animated[parentName].AsTransform3D().AffineInverse()*basis).Origin;}
