            if(!config["ragdoll"].AsBool())acceleration+=(target-point)*localConfig["stiffness"].AsSingle()/mass;velocity=(velocity+acceleration*dt)*damping;var next=point+velocity*dt;var direction=(next-anchor).Normalized();var restDirection=(basis.Basis*axis).Normalized();float angle=restDirection.AngleTo(direction);float limit=Mathf.DegToRad(localConfig["limit"].AsSingle());if(angle>limit&&angle>.000001)direction=restDirection.Slerp(direction,limit/angle);next=anchor+direction*length;if(localConfig["collision"].AsBool())next=_collision.point_motion((RefCounted)Module(owner,"world"),id,point,next,localConfig["radius"].AsDouble(),localConfig["layer"].AsInt32(),localConfig["mask"].AsInt32(),new GArray())["position"].AsVector3();bone["v"]=(next-point)/(float)Math.Max(.00001,h);bone["point"]=next;var rotation=new Quaternion(restDirection,(next-anchor).Normalized())*basis.Basis.GetRotationQuaternion();bone["pose"]=new Transform3D(new Basis(rotation)*Basis.FromScale(basis.Basis.Scale),anchor);
